-- EXECUTE is checked on the function behind operators, casts, membership
-- tests, pattern matches, grouping and set operations, as PostgreSQL's
-- executor checks it when a plan starts, even when no row is evaluated.
CREATE ROLE ox_caller;
CREATE TABLE ox_t(a integer, b text, n numeric);
INSERT INTO ox_t VALUES (1, 'x', 2.5), (2, 'y', 3.5);
GRANT ALL ON ox_t TO ox_caller;
REVOKE EXECUTE ON FUNCTION int4pl(integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION int4eq(integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION int4(numeric) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION textregexeq(text, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION upper(text) FROM PUBLIC;
SET ROLE ox_caller;
SELECT 1 + 1;
SELECT a + 1 FROM ox_t;
SELECT - a FROM ox_t;
SELECT a FROM ox_t WHERE a = 1;
SELECT a FROM ox_t ORDER BY a;
SELECT b FROM ox_t WHERE b = 'x';
SELECT b FROM ox_t WHERE b LIKE 'x%';
SELECT b FROM ox_t WHERE b ~ 'x';
SELECT n::integer FROM ox_t;
SELECT CAST(n AS integer) FROM ox_t;
SELECT sum(a) FROM ox_t;
SELECT a FROM ox_t WHERE a IN (1, 2);
SELECT a FROM ox_t WHERE a = ANY (ARRAY[1, 2]);
SELECT NULLIF(a, 1) FROM ox_t;
SELECT a IS DISTINCT FROM 1 FROM ox_t;
SELECT CASE a WHEN 1 THEN 'one' END FROM ox_t;
SELECT upper(b) FROM ox_t;
SELECT DISTINCT a FROM ox_t;
SELECT a FROM ox_t GROUP BY a;
SELECT a FROM ox_t UNION SELECT a FROM ox_t;
SELECT a FROM ox_t UNION ALL SELECT a FROM ox_t;
SELECT a FROM ox_t WHERE a IN (SELECT a FROM ox_t);
SELECT greatest(a, 0) FROM ox_t;
SELECT length(b) FROM ox_t;
RESET ROLE;
GRANT EXECUTE ON FUNCTION int4pl(integer, integer) TO ox_caller;
SET ROLE ox_caller;
SELECT a + 1 FROM ox_t;
RESET ROLE;
GRANT EXECUTE ON FUNCTION int4pl(integer, integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION int4eq(integer, integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION int4(numeric) TO PUBLIC;
GRANT EXECUTE ON FUNCTION textregexeq(text, text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION upper(text) TO PUBLIC;
REVOKE EXECUTE ON FUNCTION int4pl(integer, integer) FROM ox_caller;
DROP TABLE ox_t;
DROP ROLE ox_caller;
CREATE ROLE ox_caller;
CREATE DOMAIN ox_positive AS integer CHECK (VALUE + 0 > 0);
CREATE TABLE ox_d(a integer DEFAULT 1 + 1, b ox_positive, c text);
CREATE INDEX ox_d_expr ON ox_d ((a + 1));
CREATE FUNCTION ox_trig() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.c := 'trig'; RETURN NEW; END $$;
CREATE TRIGGER ox_d_trig BEFORE INSERT ON ox_d FOR EACH ROW EXECUTE FUNCTION ox_trig();
GRANT ALL ON ox_d TO ox_caller;
CREATE FUNCTION ox_eq(integer, integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS 'SELECT $1 = $2';
CREATE OPERATOR === (LEFTARG = integer, RIGHTARG = integer, FUNCTION = ox_eq);
REVOKE EXECUTE ON FUNCTION ox_eq(integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION ox_trig() FROM PUBLIC;
SET ROLE ox_caller;
INSERT INTO ox_d(b) VALUES (1);
SELECT 1 === 1;
RESET ROLE;
REVOKE EXECUTE ON FUNCTION int4pl(integer, integer) FROM PUBLIC;
SET ROLE ox_caller;
INSERT INTO ox_d(b) VALUES (1);
INSERT INTO ox_d(a, b) VALUES (5, NULL);
SELECT a, b, c FROM ox_d ORDER BY a;
PREPARE ox_p AS SELECT $1::integer + 1;
EXECUTE ox_p(1);
DEALLOCATE ox_p;
SELECT a FROM ox_d GROUP BY 1;
SELECT a FROM (SELECT 1 AS a) s WHERE a IS NOT DISTINCT FROM 1;
SELECT x FROM generate_series(1, 2) x WHERE x + 0 > 0;
RESET ROLE;
GRANT EXECUTE ON FUNCTION int4pl(integer, integer) TO PUBLIC;
DROP TABLE ox_d;
DROP DOMAIN ox_positive;
DROP OPERATOR === (integer, integer);
DROP FUNCTION ox_eq(integer, integer);
DROP FUNCTION ox_trig();
CREATE ROLE ox_caller;
CREATE TABLE ox_e(a integer, b text);
GRANT ALL ON ox_e TO ox_caller;
REVOKE EXECUTE ON FUNCTION int4pl(integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION upper(text) FROM PUBLIC;
SET ROLE ox_caller;
SELECT a + 1 FROM ox_e;
SELECT upper(b) FROM ox_e;
SELECT a FROM ox_e WHERE a + 1 > 0;
SELECT 1 WHERE false AND upper('x') = 'X';
SELECT CASE WHEN false THEN 1 + 1 END;
SELECT NULL::integer + 1;
UPDATE ox_e SET a = a + 1;
DELETE FROM ox_e WHERE a + 1 > 0;
RESET ROLE;
GRANT EXECUTE ON FUNCTION int4pl(integer, integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION upper(text) TO PUBLIC;
DROP TABLE ox_e;
DROP ROLE ox_caller;
